INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$\sin(\text{mid})$', 'Napier''s Rules', '$\sin(\text{mid}) = \tan(\text{adj}_1)\tan(\text{adj}_2) = \cos(\text{opp}_1)\cos(\text{opp}_2)$', NULL, 'Every relation in a right spherical triangle, from five circular parts.', '[{"symbol":"$\\text{mid}$","meaning":"the middle part"},{"symbol":"$\\text{adj}$","meaning":"the two parts next to it"},{"symbol":"$\\text{opp}$","meaning":"the two parts opposite it"}]'::jsonb, 'Parts: the two legs, and the complements of the other side and the two oblique angles.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Trigonometry' AND t."subject" = 'Mathematics' AND s."normKey" = 'spherical trigonometry' AND s."active"), 'Right spherical triangles', true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Trigonometry' AND t."subject" = 'Mathematics'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
